const express = require('express');
const crypto = require('crypto');
const { MongoClient } = require('mongodb');

class TokenService {
  constructor(db) {
    this.db = db;
    this.tokens = db.collection('tokens');
    this.HMAC_SECRET = process.env.HMAC_SECRET || crypto.randomBytes(32);
  }

  generateToken(userId, scope) {
    const payload = { userId, scope, iat: Date.now() };
    const data = Buffer.from(JSON.stringify(payload)).toString('base64url');
    const sig = crypto.createHmac('sha256', this.HMAC_SECRET)
      .update(data).digest('base64url');
    return `${data}.${sig}`;
  }

  verifyToken(token) {
    const parts = token.split('.');
    if (parts.length !== 2) return null;
    const [data, sig] = parts;
    const expected = crypto.createHmac('sha256', this.HMAC_SECRET)
      .update(data).digest('base64url');
    const sigBuf = Buffer.from(sig);
    const expectedBuf = Buffer.from(expected);
    if (sigBuf.length !== expectedBuf.length) {
      return null;
    }
    if (!crypto.timingSafeEqual(sigBuf, expectedBuf)) {
      return null;
    }
    return JSON.parse(Buffer.from(data, 'base64url').toString());
  }
}

class PermissionResolver {
  constructor(db) {
    this.db = db;
    this.roles = db.collection('roles');
    this.permCache = new Map();
  }

  async resolvePermissions(user) {
    if (this.permCache.has(user._id.toString())) {
      return this.permCache.get(user._id.toString());
    }
    const role = await this.roles.findOne({ name: user.role });
    const basePerms = role ? role.permissions : [];
    const userPerms = user.permissions || [];
    const merged = this.mergePermissions(basePerms, userPerms);
    this.permCache.set(user._id.toString(), merged);
    return merged;
  }

  mergePermissions(rolePerms, userPerms) {
    const result = new Set(rolePerms);
    for (const perm of userPerms) {
      if (perm.startsWith('-')) {
        result.delete(perm.substring(1));
      } else {
        result.add(perm);
      }
    }
    return Array.from(result);
  }
}

class AuditLog {
  constructor(db) {
    this.db = db;
    this.logs = db.collection('audit_logs');
  }

  async log(action, actor, target, metadata) {
    await this.logs.insertOne({
      action, actor, target, metadata,
      timestamp: new Date()
    });
  }
}

class UserService {
  constructor(db, permResolver, auditLog) {
    this.db = db;
    this.users = db.collection('users');
    this.permResolver = permResolver;
    this.auditLog = auditLog;
    this.SENSITIVE_FIELDS = ['passwordHash', 'totpSecret', 'recoveryKeys'];
    this.ADMIN_FIELDS = ['role', 'permissions', 'isActive', 'isSuperAdmin'];
  }

  sanitizeForResponse(user) {
    const clean = { ...user };
    for (const field of this.SENSITIVE_FIELDS) {
      delete clean[field];
    }
    return clean;
  }

  validateUpdatePayload(updates, actorPerms) {
    const allowed = ['name', 'email', 'avatar', 'bio', 'locale', 'theme'];
    const adminAllowed = [...allowed, ...this.ADMIN_FIELDS];
    const hasAdminPerm = actorPerms.includes('users.admin');
    const allowList = hasAdminPerm ? adminAllowed : allowed;
    const sanitized = {};
    for (const key of Object.keys(updates)) {
      if (allowList.includes(key)) {
        sanitized[key] = updates[key];
      }
    }
    return sanitized;
  }

  async updateUser(userId, updates, actor) {
    const actorPerms = await this.permResolver.resolvePermissions(actor);
    const sanitized = this.validateUpdatePayload(updates, actorPerms);
    if (Object.keys(sanitized).length === 0) {
      throw new Error('No valid fields to update');
    }
    await this.users.updateOne({ _id: userId }, { $set: sanitized });
    await this.auditLog.log('user.update', actor._id, userId, {
      fields: Object.keys(sanitized)
    });
    return this.getUser(userId);
  }

  async getUser(userId) {
    return this.users.findOne({ _id: userId });
  }
}

class InviteService {
  constructor(db, userService, tokenService, auditLog) {
    this.db = db;
    this.invites = db.collection('invites');
    this.userService = userService;
    this.tokenService = tokenService;
    this.auditLog = auditLog;
  }

  async createInvite(inviterUser, targetEmail, assignedRole, options = {}) {
    const inviterPerms = await this.userService.permResolver.resolvePermissions(inviterUser);
    if (!inviterPerms.includes('users.invite')) {
      throw new Error('Permission denied: cannot create invites');
    }
    const roleHierarchy = ['viewer', 'editor', 'admin', 'superadmin'];
    const inviterRoleIdx = roleHierarchy.indexOf(inviterUser.role);
    const targetRoleIdx = roleHierarchy.indexOf(assignedRole);
    if (targetRoleIdx > inviterRoleIdx) {
      throw new Error('Cannot assign role higher than your own');
    }
    if (targetRoleIdx === -1) {
      throw new Error('Invalid role specified');
    }
    const invite = {
      email: targetEmail,
      role: assignedRole,
      invitedBy: inviterUser._id,
      createdAt: new Date(),
      expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
      status: 'pending',
    };
    const result = await this.invites.insertOne(invite);
    invite._id = result.insertedId;
    const token = this.tokenService.generateToken(invite._id, 'invite');
    await this.auditLog.log('invite.create', inviterUser._id, targetEmail, { role: assignedRole });
    return { invite, token };
  }

  async acceptInvite(token, userDetails) {
    const payload = this.tokenService.verifyToken(token);
    if (!payload) throw new Error('Invalid token');
    if (payload.scope !== 'invite') throw new Error('Invalid token scope');
    const invite = await this.invites.findOne({ _id: payload.userId });
    if (!invite) throw new Error('Invite not found');
    if (invite.status !== 'pending') throw new Error('Invite already used');
    if (new Date() > invite.expiresAt) throw new Error('Invite expired');
    const allowedProfileFields = ['avatar', 'bio', 'locale', 'theme'];
    const safeProfile = {};
    if (userDetails.profile && typeof userDetails.profile === 'object') {
      for (const key of Object.keys(userDetails.profile)) {
        if (allowedProfileFields.includes(key) && typeof userDetails.profile[key] === 'string') {
          safeProfile[key] = userDetails.profile[key];
        }
      }
    }
    const newUser = {
      email: invite.email,
      name: typeof userDetails.name === 'string' ? userDetails.name.slice(0, 100) : 'User',
      role: invite.role,
      permissions: [],
      isActive: true,
      isSuperAdmin: false,
      createdAt: new Date(),
      createdVia: 'invite',
      inviteId: invite._id,
      ...safeProfile
    };
    const result = await this.userService.users.insertOne(newUser);
    await this.invites.updateOne(
      { _id: invite._id },
      { $set: { status: 'accepted', acceptedAt: new Date() } }
    );
    await this.auditLog.log('invite.accept', result.insertedId, invite._id, {});
    return { userId: result.insertedId };
  }
}

function createApp(db) {
  const app = express();
  app.use(express.json({ limit: '10kb' }));

  const tokenService = new TokenService(db);
  const permResolver = new PermissionResolver(db);
  const auditLog = new AuditLog(db);
  const userService = new UserService(db, permResolver, auditLog);
  const inviteService = new InviteService(db, userService, tokenService, auditLog);

  const authenticate = async (req, res, next) => {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Unauthorized' });
    }
    const token = authHeader.slice(7);
    const payload = tokenService.verifyToken(token);
    if (!payload || payload.scope !== 'session') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    const user = await userService.getUser(payload.userId);
    if (!user || !user.isActive) {
      return res.status(401).json({ error: 'User not found or inactive' });
    }
    req.user = user;
    next();
  };

  app.post('/api/invites', authenticate, async (req, res) => {
    try {
      const { email, role } = req.body;
      if (typeof email !== 'string' || typeof role !== 'string') {
        return res.status(400).json({ error: 'Invalid input' });
      }
      const result = await inviteService.createInvite(req.user, email, role);
      res.json({ inviteId: result.invite._id, token: result.token });
    } catch (e) {
      res.status(403).json({ error: e.message });
    }
  });

  app.post('/api/invites/accept', async (req, res) => {
    try {
      const { token, name, profile } = req.body;
      if (typeof token !== 'string') {
        return res.status(400).json({ error: 'Invalid token' });
      }
      const result = await inviteService.acceptInvite(token, { name, profile });
      const sessionToken = tokenService.generateToken(result.userId, 'session');
      res.json({ userId: result.userId, token: sessionToken });
    } catch (e) {
      res.status(400).json({ error: e.message });
    }
  });

  app.patch('/api/users/:id', authenticate, async (req, res) => {
    try {
      const updated = await userService.updateUser(req.params.id, req.body, req.user);
      res.json(userService.sanitizeForResponse(updated));
    } catch (e) {
      res.status(400).json({ error: e.message });
    }
  });

  return app;
}

module.exports = { createApp, UserService, InviteService, TokenService };
